--[[
	This Lua script is used to generate the link to IsItCicada
  ]]

local p = {}

-- from https://github.com/daurnimator/lua-http/blob/master/http/util.lua
local function char_to_pchar(c)
	return string.format("%%%02X", c:byte(1,1))
end
local function encodeURIComponent(str)
	return (str:gsub("[^%w%-_%.%!%~%*%'%(%)]", char_to_pchar))
end

function p.generateLink(frame)
	local template_frame = frame:getParent()

	local message = template_frame.args['message']

	return "https://cicada-solvers.github.io/isitcicada#message=" .. encodeURIComponent(message)
end

return p
